import { createWorkspace, teardownWorkspace, type Workspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "node:fs/promises";

const RESULT_PATH = "/home/user/dual-role/result.json";
const S3_ENDPOINT = "REDACTED";

async function main(): Promise<void> {
  // Step 1: Provision both workspaces concurrently
  const [writerResponse, readerResponse] = await Promise.all([
    createWorkspace("writer-ws", { credentials: { role: "Editor" } }),
    createWorkspace("reader-ws", { credentials: { role: "ReadOnly" } }),
  ]);

  // Step 2: Validate both responses
  if (writerResponse.error) {
    throw new Error(`Failed to create writer-ws workspace: ${writerResponse.error}`);
  }
  if (readerResponse.error) {
    throw new Error(`Failed to create reader-ws workspace: ${readerResponse.error}`);
  }

  const writerWorkspace: Workspace = writerResponse.data;
  const readerWorkspace: Workspace = readerResponse.data;

  if (!writerWorkspace.bucket || !writerWorkspace.credentials?.accessKeyId || !writerWorkspace.credentials?.secretAccessKey) {
    throw new Error(
      `writer-ws workspace response is missing required fields. Got: ${JSON.stringify(writerWorkspace)}`
    );
  }
  if (!readerWorkspace.bucket || !readerWorkspace.credentials?.accessKeyId || !readerWorkspace.credentials?.secretAccessKey) {
    throw new Error(
      `reader-ws workspace response is missing required fields. Got: ${JSON.stringify(readerWorkspace)}`
    );
  }

  // Step 3: Build two S3 clients, each using ONLY its workspace's scoped credentials
  const editorClient = new S3Client({
    region: "REDACTED",
    endpoint: S3_ENDPOINT,
    credentials: {
      accessKeyId: writerWorkspace.credentials.accessKeyId,
      secretAccessKey: writerWorkspace.credentials.secretAccessKey,
    },
  });

  const readonlyClient = new S3Client({
    region: "REDACTED",
    endpoint: S3_ENDPOINT,
    credentials: {
      accessKeyId: readerWorkspace.credentials.accessKeyId,
      secretAccessKey: readerWorkspace.credentials.secretAccessKey,
    },
  });

  let writer_put_ok = false;
  let readonly_put_blocked = false;

  try {
    // Step 4a: Editor PUT — expect success
    try {
      await editorClient.send(
        new PutObjectCommand({
          Bucket: writerWorkspace.bucket,
          Key: "note.txt",
          Body: "hello dual role",
        })
      );
      writer_put_ok = true;
    } catch (err) {
      console.error("Editor PutObject failed (unexpected):", err);
      writer_put_ok = false;
    }

    // Step 4b: ReadOnly PUT — expect rejection
    try {
      await readonlyClient.send(
        new PutObjectCommand({
          Bucket: readerWorkspace.bucket,
          Key: "note.txt",
          Body: "should be blocked",
        })
      );
      // If we reach here the write unexpectedly succeeded
      console.warn("ReadOnly PutObject unexpectedly succeeded.");
      readonly_put_blocked = false;
    } catch (err: unknown) {
      const e = err as Record<string, unknown>;
      const name = typeof e?.name === "string" ? e.name : "";
      const code = typeof e?.Code === "string" ? e.Code : "";
      const status =
        typeof (e as { $metadata?: { httpStatusCode?: number } })?.$metadata?.httpStatusCode === "number"
          ? (e as { $metadata: { httpStatusCode: number } }).$metadata.httpStatusCode
          : undefined;

      const isAccessDenied =
        name === "AccessDenied" ||
        code === "AccessDenied" ||
        name === "NotImplemented" ||
        code === "NotImplemented" ||
        status === 403;

      if (isAccessDenied) {
        readonly_put_blocked = true;
      } else {
        console.error("ReadOnly PutObject threw an unexpected error:", err);
        readonly_put_blocked = false;
      }
    }

    // Step 5: Write result summary
    const summary = {
      writer_bucket: writerWorkspace.bucket,
      reader_bucket: readerWorkspace.bucket,
      writer_put_ok,
      readonly_put_blocked,
    };

    await writeFile(RESULT_PATH, JSON.stringify(summary, null, 2), "utf-8");
    console.log("Result written to", RESULT_PATH);
    console.log(JSON.stringify(summary, null, 2));
  } finally {
    // Step 6: Always tear down both workspaces, even if an error occurred above
    const [teardownWriterResult, teardownReaderResult] = await Promise.all([
      teardownWorkspace(writerWorkspace),
      teardownWorkspace(readerWorkspace),
    ]);

    if (teardownWriterResult.error) {
      console.error("Warning: failed to tear down writer-ws:", teardownWriterResult.error);
    } else {
      console.log("writer-ws torn down successfully.");
    }

    if (teardownReaderResult.error) {
      console.error("Warning: failed to tear down reader-ws:", teardownReaderResult.error);
    } else {
      console.log("reader-ws torn down successfully.");
    }
  }
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
